using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(Endpoint), new Azure.AzureKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY")));

        return client.GetChatClient(DeploymentName).AsIChatClient();
    }

    public static ReportingConfiguration CreateReportingConfig(
        string storagePath,
        params IEvaluator[] evaluators)
    {
        return new ReportingConfiguration(
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            storageRootPath: storagePath);
    }

    public static IEvaluator[] QualityEvaluators =>
    [
        new CoherenceEvaluator(),
        new RelevanceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI calls emit OpenTelemetry traces and captures
/// token usage metrics through the evaluation reporting pipeline.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static ReportingConfiguration? s_config;
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "telemetry");

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalConfig.CreateReportingConfig(StoragePath);
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTokenUsage()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(ChatCompletion_EmitsTokenUsage));

        var client = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2 + 2?")
        };

        var response = await client.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Message.Text?.Length > 0, "Response should not be empty");

        await scenario.EvaluateAsync(messages, response);
    }

    [TestMethod]
    public async Task ChatCompletion_TracesActivitySpans()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("OpenAI") || source.Name.Contains("AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData,
            ActivityStopped = activity => activities.Add(activity)
        };
        ActivitySource.AddActivityListener(listener);

        var client = EvalConfig.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello")
        };

        await client.GetResponseAsync(messages);

        Assert.IsTrue(activities.Count > 0, "Expected at least one activity span from the AI call");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates AI responses against coherence, relevance, fluency,
/// and groundedness metrics using an LLM-as-judge approach.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "quality");

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalConfig.CreateReportingConfig(StoragePath, EvalConfig.QualityEvaluators);
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MeetsQualityThresholds));

        var client = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management skills?")
        };

        var response = await client.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        var coherence = scenario.GetNumericMetricValue(CoherenceEvaluator.CoherenceMetricName);
        var relevance = scenario.GetNumericMetricValue(RelevanceEvaluator.RelevanceMetricName);
        var fluency = scenario.GetNumericMetricValue(FluencyEvaluator.FluencyMetricName);

        Assert.IsTrue(coherence >= 3, $"Coherence {coherence} below threshold 3");
        Assert.IsTrue(relevance >= 3, $"Relevance {relevance} below threshold 3");
        Assert.IsTrue(fluency >= 3, $"Fluency {fluency} below threshold 3");
    }

    [TestMethod]
    public async Task CoachResponse_IsGrounded()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_IsGrounded));

        var client = scenario.ChatConfiguration!.ChatClient;

        var context = "Research shows that breaking tasks into 25-minute focused intervals " +
                      "(Pomodoro Technique) improves productivity by reducing cognitive fatigue.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a coaching assistant. Use this context: {context}"),
            new(ChatRole.User, "What technique can help me focus better?")
        };

        var response = await client.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        var groundedness = scenario.GetNumericMetricValue(GroundednessEvaluator.GroundednessMetricName);
        Assert.IsTrue(groundedness >= 3, $"Groundedness {groundedness} below threshold 3");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs identical prompts against a baseline and candidate configuration,
/// then compares quality metrics side-by-side via the reporting storage.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "compare");

    private static readonly (string Prompt, string SystemMessage)[] Scenarios =
    [
        ("How do I set meaningful goals?", "You are a helpful coaching assistant."),
        ("What habits lead to success?", "You are a helpful coaching assistant."),
        ("How do I overcome procrastination?", "You are a helpful coaching assistant."),
    ];

    [TestMethod]
    public async Task Baseline_vs_Candidate_QualityComparison()
    {
        var baselineConfig = EvalConfig.CreateReportingConfig(
            Path.Combine(StoragePath, "baseline"), EvalConfig.QualityEvaluators);

        var candidateConfig = EvalConfig.CreateReportingConfig(
            Path.Combine(StoragePath, "candidate"), EvalConfig.QualityEvaluators);

        var baselineScores = new List<(double Coherence, double Relevance)>();
        var candidateScores = new List<(double Coherence, double Relevance)>();

        foreach (var (prompt, systemMessage) in Scenarios)
        {
            var scenarioName = $"Compare_{prompt[..20].Replace(' ', '_')}";

            // Run baseline
            await using (var scenario = await baselineConfig.CreateScenarioRunAsync(scenarioName))
            {
                var messages = new List<ChatMessage>
                {
                    new(ChatRole.System, systemMessage),
                    new(ChatRole.User, prompt)
                };

                var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
                await scenario.EvaluateAsync(messages, response);

                baselineScores.Add((
                    scenario.GetNumericMetricValue(CoherenceEvaluator.CoherenceMetricName),
                    scenario.GetNumericMetricValue(RelevanceEvaluator.RelevanceMetricName)));
            }

            // Run candidate (same model, demonstrating the pattern for swapping configs)
            await using (var scenario = await candidateConfig.CreateScenarioRunAsync(scenarioName))
            {
                var messages = new List<ChatMessage>
                {
                    new(ChatRole.System, systemMessage + " Be concise and actionable."),
                    new(ChatRole.User, prompt)
                };

                var response = await scenario.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
                await scenario.EvaluateAsync(messages, response);

                candidateScores.Add((
                    scenario.GetNumericMetricValue(CoherenceEvaluator.CoherenceMetricName),
                    scenario.GetNumericMetricValue(RelevanceEvaluator.RelevanceMetricName)));
            }
        }

        // Report comparison
        var avgBaselineCoherence = baselineScores.Average(s => s.Coherence);
        var avgCandidateCoherence = candidateScores.Average(s => s.Coherence);
        var avgBaselineRelevance = baselineScores.Average(s => s.Relevance);
        var avgCandidateRelevance = candidateScores.Average(s => s.Relevance);

        Console.WriteLine($"Baseline  - Coherence: {avgBaselineCoherence:F2}, Relevance: {avgBaselineRelevance:F2}");
        Console.WriteLine($"Candidate - Coherence: {avgCandidateCoherence:F2}, Relevance: {avgCandidateRelevance:F2}");

        // Both must meet minimum thresholds
        Assert.IsTrue(avgBaselineCoherence >= 2, "Baseline coherence too low");
        Assert.IsTrue(avgCandidateCoherence >= 2, "Candidate coherence too low");
    }
}

