[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "compare");

    private static readonly (string Prompt, string SystemMessage)[] Scenarios =
    [
        ("How do I set meaningful goals?", "You are a helpful coaching assistant."),
        ("What habits lead to success?", "You are a helpful coaching assistant."),
