using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI calls emit OpenTelemetry traces and captures
/// token usage metrics through the evaluation reporting pipeline.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static ReportingConfiguration? s_config;
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "telemetry");

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalConfig.CreateReportingConfig(StoragePath);
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTokenUsage()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(ChatCompletion_EmitsTokenUsage));

        var client = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2 + 2?")
        };

        var response = await client.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Message.Text?.Length > 0, "Response should not be empty");

        await scenario.EvaluateAsync(messages, response);
    }

    [TestMethod]
    public async Task ChatCompletion_TracesActivitySpans()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("OpenAI") || source.Name.Contains("AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData,
            ActivityStopped = activity => activities.Add(activity)
        };
        ActivitySource.AddActivityListener(listener);

        var client = EvalConfig.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello")
        };

        await client.GetResponseAsync(messages);

        Assert.IsTrue(activities.Count > 0, "Expected at least one activity span from the AI call");
    }
}

